import { type Permission, UsersService } from "@/client"
import useAuth from "./useAuth"

// Plain function, usable in route `beforeLoad` (no React context there).
export const hasPermission = async (permission: Permission) => {
  const { data: user } = await UsersService.readUserMe()
  return user.permissions.includes(permission)
}

const usePermissions = () => {
  const { user } = useAuth()

  const can = (permission: Permission) =>
    user?.permissions.includes(permission) ?? false

  return { can }
}

export default usePermissions
import { useSuspenseQuery } from "@tanstack/react-query"
import { createFileRoute, redirect } from "@tanstack/react-router"
import { Suspense } from "react"

import { MetricsService } from "@/client"
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card"
import { hasPermission } from "@/hooks/usePermissions"

function getMetricsQueryOptions() {
  return {
    queryFn: async () => (await MetricsService.readMetrics()).data,
    queryKey: ["metrics"],
  }
}

export const Route = createFileRoute("/_layout/metrics")({
  component: Metrics,
  beforeLoad: async () => {
    if (!(await hasPermission("metrics:read"))) {
      throw redirect({
        to: "/",
      })
    }
  },
  head: () => ({
    meta: [
      {
        title: "Metrics - FastAPI Template",
      },
    ],
  }),
})

function MetricsContent() {
  const { data } = useSuspenseQuery(getMetricsQueryOptions())

  const stats = [
    { label: "Users", value: data.users },
    { label: "Active users", value: data.active_users },
    { label: "Items", value: data.items },
  ]

  return (
    <div className="grid gap-4 md:grid-cols-3">
      {stats.map((stat) => (
        <Card key={stat.label}>
          <CardHeader>
            <CardDescription>{stat.label}</CardDescription>
            <CardTitle className="text-3xl">{stat.value}</CardTitle>
          </CardHeader>
          <CardContent />
        </Card>
      ))}
    </div>
  )
}

function Metrics() {
  return (
    <div className="flex flex-col gap-6">
      <div>
        <h1 className="text-2xl font-bold tracking-tight">Metrics</h1>
        <p className="text-muted-foreground">Basic counts</p>
      </div>
      <Suspense fallback={<p className="text-muted-foreground">Loading...</p>}>
        <MetricsContent />
      </Suspense>
    </div>
  )
}

